    private final Map<String, CompletableFuture<String>> pending = new ConcurrentHashMap<>();
    public String checkStock(String sku) throws Exception {       // a method call
        String corrId = UUID.randomUUID().toString();
        CompletableFuture<String> future = new CompletableFuture<>();
        pending.put(corrId, future);
        channel.basicPublish("", "inventory.check",
            new AMQP.BasicProperties.Builder().replyTo(replyQueue).correlationId(corrId).build(),
            sku.getBytes(StandardCharsets.UTF_8));
        return future.get(2, TimeUnit.SECONDS);                  // caller sees a method
    }
